var raw = $input.first().json;
var body = raw.body || raw;

function pick() {
  for (var i = 0; i < arguments.length; i++) {
    var key = arguments[i];
    if (body[key] !== undefined && body[key] !== null && String(body[key]).trim() !== '') {
      return String(body[key]).trim();
    }
  }
  return '—';
}

function safe(value) {
  return String(value || '—')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

var name = pick('name', 'contact_name', 'client');
var phone = pick('phone', 'tel', 'telephone');
var email = pick('email');
var company = pick('company', 'organization');
var source = pick('source', 'utm_source');
var page = pick('page', 'url', 'path');
var service = pick('service', 'task', 'request_type');
var route = pick('route', 'direction', 'destination', 'from_to');
var date = pick('date', 'travel_date', 'departure_date');
var passengers = pick('pax', 'passengers', 'people');
var payment = pick('payment', 'payment_type', 'pay_type');
var comment = pick('comment', 'message', 'details');

var now = new Date();
var minsk = now.toLocaleString('ru-RU', { timeZone: 'Europe/Minsk' });
var cleanPhone = phone.replace(/[^\d+]/g, '');

var text = '<b>Новая заявка fclass.by</b>\n\n';
text += '<b>Контакт</b>\n';
text += '👤 ' + safe(name) + '\n';
text += '📞 ' + safe(phone) + '\n';
text += '📧 ' + safe(email) + '\n';
text += '🏢 ' + safe(company) + '\n\n';
text += '<b>Квалификация</b>\n';
text += '📍 Источник: ' + safe(source) + '\n';
text += '🧭 Услуга: ' + safe(service) + '\n';
text += '✈️ Маршрут: ' + safe(route) + '\n';
text += '📅 Дата: ' + safe(date) + '\n';
text += '👥 Пассажиры: ' + safe(passengers) + '\n';
text += '💳 Оплата: ' + safe(payment) + '\n';

if (comment && comment !== '—') {
  text += '\n💬 ' + safe(comment) + '\n';
}

if (page && page !== '—') {
  text += '\n🌐 https://fclass.by' + safe(page).replace(/^https?:\/\/fclass\.by/, '') + '\n';
}

text += '\n🕐 ' + minsk;
text += '\n\n#fclass_lead #site_lead';

return {
  json: {
    text: text,
    name: name,
    phone: phone,
    cleanPhone: cleanPhone,
    email: email,
    company: company,
    source: source,
    page: page,
    service: service,
    route: route,
    date: date,
    passengers: passengers,
    payment: payment,
    comment: comment,
    timestamp: now.toISOString()
  }
};
